def max_pool(fm):
    out = []
    for i in range(0, len(fm), 2):
        row = []
        for j in range(0, len(fm[0]), 2):
            row.append(max(fm[i][j], fm[i][j + 1], fm[i + 1][j], fm[i + 1][j + 1]))
        out.append(row)
    return out

def avg_pool(fm):
    out = []
    for i in range(0, len(fm), 2):
        row = []
        for j in range(0, len(fm[0]), 2):
            row.append((fm[i][j] + fm[i][j + 1] + fm[i + 1][j] + fm[i + 1][j + 1]) / 4)
        out.append(row)
    return out

import numpy as np

def max_pool_np(X):
    C, H, W = X.shape
    return X.reshape(C, H // 2, 2, W // 2, 2).max(axis=(2, 4))

def global_avg_pool(X):
    return X.mean(axis=(1, 2))

def receptive_field(layers):
    r, j = 1, 1
    for kernel, stride in layers:
        r += (kernel - 1) * j
        j *= stride
    return r
